import{_ as a}from"./chunks/rayrai_usd_shadow_hand_cube.B-3i7-qS.js";import{_ as i,o as s,c as t,a5 as o}from"./chunks/framework.DrDMl0tG.js";const b=JSON.parse('{"title":"Server Example: Shadow Hand USD Cube","description":"","frontmatter":{},"headers":[],"relativePath":"sections/examples/server/shadow_hand_usd_cube.md","filePath":"sections/examples/server/shadow_hand_usd_cube.md"}'),d={name:"sections/examples/server/shadow_hand_usd_cube.md"};function r(n,e,h,c,l,u){return s(),t("div",null,[...e[0]||(e[0]=[o('<h1 id="server-example-shadow-hand-usd-cube" tabindex="-1">Server Example: Shadow Hand USD Cube <a class="header-anchor" href="#server-example-shadow-hand-usd-cube" aria-label="Permalink to &quot;Server Example: Shadow Hand USD Cube&quot;">​</a></h1><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>Loads NVIDIA Isaac Sim&#39;s Shadow Robot ShadowHand USD scene directly with <code>World(shadow_hand.usd)</code> and places a RaiSim rigid-body cube at the Isaac Lab in-hand cube start pose. The constructor imports the USD Physics rigid bodies and joints as a RaiSim articulated system. See <a href="./../../OpenUSD.html">OpenUSD Loading</a>.</p><p>The cube is a native RaiSim box. The example fails fast if the ShadowHand articulation, collision bodies, or visual meshes are not imported.</p><p><img src="'+a+'" alt="ShadowHand USD collision geometry with a cube above the hand"></p><h2 id="target" tabindex="-1">Target <a class="header-anchor" href="#target" aria-label="Permalink to &quot;Target&quot;">​</a></h2><p>CMake target: <code>shadow_hand_usd_cube</code> (C++20).</p><h2 id="run" tabindex="-1">Run <a class="header-anchor" href="#run" aria-label="Permalink to &quot;Run&quot;">​</a></h2><p>Run the build-tree executable:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./build-examples/examples/shadow_hand_usd_cube</span></span></code></pre></div><p>On Windows, run <code>shadow_hand_usd_cube.exe</code> instead. This example uses RaisimServer. Start <code>rayrai_tcp_viewer</code> and connect to port 8080. The viewer remains interactive while the simulation runs.</p><h2 id="details" tabindex="-1">Details <a class="header-anchor" href="#details" aria-label="Permalink to &quot;Details&quot;">​</a></h2><ul><li>Loads <code>rsc/isaac/Robots/ShadowRobot/ShadowHand/shadow_hand.usd</code> with the <code>World</code> constructor.</li><li>Uses RaiSim&#39;s bundled OpenUSD runtime directly; no Assimp USD importer or USD-specific build switch is required.</li><li>Throws an error if the imported scene does not contain an articulated system named <code>shadow_hand</code> with collision bodies and visual meshes.</li><li>Places the ShadowHand base at <code>(0, 0, 0.5)</code>.</li><li>Drives the hand toward the imported nominal configuration with PD control. While the viewer has the simulation paused, joint positions edited in the viewer become the new PD targets.</li><li>Creates a dynamic 6.5 cm cube at <code>(0, -0.39, 1.05)</code>, matching the Isaac Lab Shadow Hand cube task&#39;s initial object pose.</li></ul>',13)])])}const _=i(d,[["render",r]]);export{b as __pageData,_ as default};
